from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 260, "מסילה חלקה AB על שולחן: A בגובה 45 סנטימטר מעל השולחן, B אופקית בקצה השולחן. השולחן בגובה 80 סנטימטר מעל הרצפה. C מתחת ל-B, והכדור פוגע ברצפה בנקודה D")
    g.ground(30, 520, 230)
    g.rect(60, 120, 220, 10, fill="var(--d-fill)"); g.line(80, 130, 80, 230, width=3); g.line(260, 130, 260, 230, width=3)
    g.path("M 140,40 Q 160,118 270,118", width=3)
    g.ball(140, 40, 6); g.text(130, 36, "A", anchor="end"); g.text(272, 108, "B", anchor="start")
    g.dim(110, 40, 110, 118, "h", offset=0); g.dim(40, 120, 40, 230, "H", offset=0)
    g.text(270, 250, "C"); g.text(400, 250, "D")
    g.path("M 272,118 Q 340,124 400,228", stroke="var(--d-dim)", width=1.4, dash="5 4")
    return g

E(id="bagrut-2008-q4", year=2008, label="2008 שאלה 4", topic="momentum", sub="mom-collisions", diff=3, fig=fig,
  stem=r"על שולחן עומדת מסילה חלקה $AB$. הנקודה $A$ גבוהה ב-$h = 45\,\text{cm}$ מעל השולחן, והשולחן גבוה ב-$H = 80\,\text{cm}$ מעל הרצפה. בקצה $B$ המסילה אופקית. הנקודה $C$ נמצאת על הרצפה, בדיוק מתחת ל-$B$. מזניחים את התנגדות האוויר. משחררים כדור קטן (\"כדור 1\") ממנוחה ב-$A$. הכדור מחליק על המסילה בלי להתגלגל, עוזב אותה ב-$B$ ופוגע ברצפה בנקודה $D$.",
  parts=[
    P("א", r"בסעיף הזה מתייחסים לתנועה של כדור 1 מ-$B$ עד $D$. איזו תנועה יש לכדור בכיוון האופקי, ואיזו בכיוון האנכי (במהירות קבועה, בתאוצה קבועה, או תנועה אחרת)? נמקו.", choice(["אופקית במהירות קבועה, אנכית בתאוצה קבועה", "אופקית בתאוצה קבועה, אנכית במהירות קבועה", "בשני הכיוונים בתאוצה קבועה", "בשני הכיוונים במהירות קבועה"], 0), ["principle"], [
        S(r"בכיוון האופקי", r"אין כוח אופקי על הכדור, ולכן אין תאוצה אופקית", r"a_x = 0"),
        S(r"בכיוון האנכי", r"פועל רק כוח הכובד, ולכן התאוצה היא תאוצת הכובד", r"mg = m a_y \;\Rightarrow\; a_y = g", eq=r"\Sigma\vec F = m\vec a"),
    ], r"אופקית במהירות קבועה, אנכית בתאוצה קבועה", key=r"אופקי שוות-מהירות ; אנכי שוות-תאוצה"),
    P("ב", r"מה המרחק $CD$?", num(1.2, "m"), ["principle"], [
        S(r"המהירות ב-B", r"המסילה חלקה, ולכן האנרגיה המכנית נשמרת. המסה מצטמצמת. ממירים סנטימטרים למטרים", r"m \cdot 10 \cdot 0.45 = \tfrac{1}{2}m\,v_B^2 \;\Rightarrow\; v_B = 3\,\text{m/s}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"זמן הנפילה", r"בציר האנכי הכדור יוצא בלי מהירות. כלפי מטה חיובי", r"0.8 = \tfrac{1}{2} \cdot 10\,t^2 \;\Rightarrow\; t = 0.4\,\text{s}", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"המרחק", r"בציר האופקי המהירות קבועה", r"CD = 3 \cdot 0.4 = 1.2\,\text{m}"),
    ], r"$1.2\,\text{m}$", key=r"CD=1.2 m"),
    P("ג", r"הכדור מתנגש ברצפה התנגשות אלסטית. לאיזה גובה מרבי מעל הרצפה הוא יעלה אחרי ההתנגשות ב-$D$? נמקו.", num(0.8, "m"), ["principle"], [
        S(r"התנגשות אלסטית ברצפה", r"הרצפה דוחפת רק כלפי מעלה. הרכיב האנכי של המהירות מתהפך באותו גודל, והרכיב האופקי לא משתנה", r"v_y' = -v_y,\qquad v_x' = v_x"),
        S(r"הגובה", r"הרכיב האנכי זהה לזה שהיה לכדור כשנפל מגובה השולחן, ולכן הוא עולה בדיוק לאותו גובה. בשיא נשארת לו רק המהירות האופקית", r"h_{\max} = H = 0.8\,\text{m}"),
    ], r"$0.8\,\text{m}$", key=r"0.8 m"),
    P("ד", r"במקרה שני מניחים בקצה $B$ את \"כדור 2\", שמסתו שווה למסה של כדור 1. שוב משחררים את כדור 1 ממנוחה ב-$A$. הוא מחליק, מתנגש בכדור 2 התנגשות פלסטית, והכדורים נדבקים זה לזה. מה המרחק בין הנקודה שבה הכדורים פוגעים ברצפה לבין $C$?", num(0.6, "m"), ["principle"], [
        S(r"שימור תנע", r"בהתנגשות אין כוח חיצוני אופקי. המסות שוות, והכדורים נדבקים", r"m \cdot 3 + m \cdot 0 = 2m\,u \;\Rightarrow\; u = 1.5\,\text{m/s}", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"המרחק", r"הגובה זהה, ולכן זמן הנפילה זהה לסעיף ב", r"d = 1.5 \cdot 0.4 = 0.6\,\text{m}"),
    ], r"$0.6\,\text{m}$", key=r"0.6 m"),
    P("ה", r"במקרה שלישי מניחים בקצה $B$ את \"כדור 3\", שמסתו שווה למסה של כדור 1. שוב משחררים את כדור 1 ממנוחה ב-$A$, והוא מתנגש בכדור 3 התנגשות חזיתית אלסטית. האם ייתכן שכדור 3 יפגע ברצפה רחוק יותר מהמרחק $CD$? נמקו.", choice(["כן", "לא"], 1), ["principle"], [
        S(r"שימור תנע", r"המסות שוות", r"m \cdot 3 + 0 = m\,u_1 + m\,u_3", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"התנגשות אלסטית", r"מהירות ההתקרבות שווה למהירות ההתרחקות", r"3 - 0 = -(u_1 - u_3)", eq=r"v_A - v_B = -(u_A - u_B)"),
        S(r"פותרים", r"מחברים את שתי המשוואות. כדור 1 נעצר, וכדור 3 יוצא במהירות שהייתה לכדור 1", r"u_3 = 3\,\text{m/s},\qquad u_1 = 0"),
        S(r"מסקנה", r"אותה מהירות ואותו זמן נפילה כמו בסעיף ב", r"d = 3 \cdot 0.4 = 1.2\,\text{m} = CD"),
    ], r"לא: כדור 3 נוחת בדיוק ב-$D$", key=r"לא יתכן"),
  ],
  concepts=["שימור אנרגיה", "זריקה אופקית", "התנגשות אלסטית ופלסטית", "התנגשות אלסטית ברצפה"],
  summary=r"כדור שגולש במסילה ונופל מהשולחן: מרחק הנחיתה, ניתור אלסטי, ומה משתנה כשהוא פוגע קודם בכדור זהה.",
  review="הנחה שלי.\nבסעיף א התלמיד בוחר את סוג התנועה מתוך ארבע אפשרויות.\nמה לבדוק: רק לאשר.")
